import {createChatOrchestrator} from './chatOrchestrator.js';
import type {AIProvider, MessageChunk, SendMessageParams} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

function session(): ChatSession {
  return {sessionId: 's1', userId: 'u1', entries: [{role: 'user', content: 'hi', timestamp: SENT_AT}]};
}

function throwingProvider(value: unknown): AIProvider {
  return {
    // eslint-disable-next-line require-yield
    async *sendMessage(_params: SendMessageParams): AsyncGenerator<MessageChunk> {
      throw value;
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
}

const promptBuilder = new PromptBuilder({identity: 'You are a test assistant.'});

describe('onError — non-Error rejection wrapping', () => {
  it('wraps a string rejection in an Error and passes the original as cause', async () => {
    let received: Error | undefined;
    const orchestrator = createChatOrchestrator(throwingProvider('oops'), promptBuilder, undefined, {
      hooks: {
        onError: async (_session, error) => {
          received = error;
        },
      },
    });

    await orchestrator.processMessage(session()).catch(() => {});

    expect(received).toBeInstanceOf(Error);
    expect(received?.cause).toBe('oops');
  });
});

